style.css:
@-moz-document domain("roblox.com") {
/* ---------- FOTO DE FONDO: YA ESTÁ INCLUIDA ---------- */
html,
body {
    background: transparent !important;
    background-color: transparent !important;
}

body::before {
    content: "";
    position: fixed;
    inset: 0;
    width: 100vw;
    height: 100vh;

    background-image: url("data:image/jpeg;base64,");
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;

    z-index: -999999;
    pointer-events: none;
}

/* Capa oscura muy suave para mejorar la lectura */
body::after {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, .18);
    z-index: -999998;
    pointer-events: none;
}

/* ---------- QUITAR FONDOS BLANCOS ---------- */
#app,
#content,
#navigation,
#header,
.rbx-body,
.rbx-left-col,
.rbx-right-col,
.container-main,
.main-content,
.content,
.content-container,
.page-content,
.section,
.section-content,
.home-container,
.main-container,
.sidebar,
.left-col,
nav,
main {
    background: transparent !important;
    background-color: transparent !important;
}

/* ---------- BARRA SUPERIOR ---------- */
#header,
.rbx-header,
.rbx-navbar,
.navbar,
header {
    background: rgba(12, 12, 15, .58) !important;
    backdrop-filter: blur(18px) saturate(125%) !important;
    -webkit-backdrop-filter: blur(18px) saturate(125%) !important;
    border-bottom: 1px solid rgba(255,255,255,.13) !important;
    box-shadow: 0 4px 25px rgba(0,0,0,.22) !important;
}

/* ---------- BARRA IZQUIERDA: FOTO VISIBLE ---------- */
#navigation,
.rbx-left-col,
.left-col,
.sidebar {
    background: rgba(8, 8, 11, .28) !important;
    backdrop-filter: blur(14px) saturate(115%) !important;
    -webkit-backdrop-filter: blur(14px) saturate(115%) !important;
    border-right: 1px solid rgba(255,255,255,.09) !important;
    box-shadow: 5px 0 25px rgba(0,0,0,.16) !important;
}

/* ---------- MENÚ ---------- */
#navigation a,
.rbx-left-col a,
.sidebar a {
    background: transparent !important;
    border-radius: 12px !important;
    transition: background .18s ease, transform .18s ease, box-shadow .18s ease !important;
}

#navigation a:hover,
.rbx-left-col a:hover,
.sidebar a:hover {
    background: rgba(255,255,255,.11) !important;
    transform: translateX(2px);
    box-shadow: 0 4px 14px rgba(0,0,0,.14) !important;
}

#navigation a[aria-current="page"],
.rbx-left-col a[aria-current="page"] {
    background: rgba(255,255,255,.15) !important;
    box-shadow: inset 0 0 0 1px rgba(255,255,255,.07),
                0 5px 18px rgba(0,0,0,.14) !important;
}

/* ---------- ZONA CENTRAL ---------- */
.container-main,
.main-content,
.content,
.content-container,
.page-content,
.section,
.section-content,
.home-container,
.main-container {
    background: transparent !important;
    background-color: transparent !important;
}

/* ---------- TARJETAS / JUEGOS ---------- */
.game-card,
[class*="game-card"],
[class*="GameCard"],
[class*="experience-card"],
[class*="ExperienceCard"] {
    background: rgba(12,12,16,.40) !important;
    backdrop-filter: blur(9px) saturate(115%) !important;
    -webkit-backdrop-filter: blur(9px) saturate(115%) !important;
    border: 1px solid rgba(255,255,255,.09) !important;
    border-radius: 14px !important;
    box-shadow: 0 8px 24px rgba(0,0,0,.18) !important;
    transition: transform .20s ease, background .20s ease, box-shadow .20s ease !important;
}

.game-card:hover,
[class*="game-card"]:hover,
[class*="GameCard"]:hover {
    background: rgba(12,12,16,.53) !important;
    transform: translateY(-2px) !important;
    box-shadow: 0 12px 30px rgba(0,0,0,.26) !important;
}

/* ---------- BUSCADOR ---------- */
input,
textarea,
[role="textbox"] {
    background: rgba(255,255,255,.11) !important;
    backdrop-filter: blur(11px) !important;
    -webkit-backdrop-filter: blur(11px) !important;
    border: 1px solid rgba(255,255,255,.14) !important;
    border-radius: 12px !important;
    color: #fff !important;
}

input:focus,
textarea:focus,
[role="textbox"]:focus {
    background: rgba(255,255,255,.15) !important;
    box-shadow: 0 0 0 3px rgba(255,255,255,.07) !important;
    outline: none !important;
}

/* ---------- BOTONES ---------- */
button {
    background: rgba(15,15,19,.46) !important;
    backdrop-filter: blur(9px) !important;
    -webkit-backdrop-filter: blur(9px) !important;
    border: 1px solid rgba(255,255,255,.09) !important;
    border-radius: 10px !important;
    transition: background .18s ease, transform .18s ease !important;
}

button:hover {
    background: rgba(255,255,255,.12) !important;
    transform: translateY(-1px);
}

/* ---------- CHAT / VENTANAS ---------- */
[class*="chat"],
[class*="Chat"],
[role="dialog"],
.modal,
[class*="modal"],
[class*="Modal"] {
    background: rgba(10,10,13,.64) !important;
    backdrop-filter: blur(18px) saturate(120%) !important;
    -webkit-backdrop-filter: blur(18px) saturate(120%) !important;
    border: 1px solid rgba(255,255,255,.10) !important;
    box-shadow: 0 15px 45px rgba(0,0,0,.30) !important;
}

/* ---------- TEXTO ---------- */
body,
h1,h2,h3,h4,h5,h6,
p,span,a,button {
    text-shadow: 0 2px 5px rgba(0,0,0,.72) !important;
}

h1,h2,h3 {
    text-shadow: 0 2px 8px rgba(0,0,0,.82) !important;
}

/* ---------- SCROLLBAR ---------- */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: rgba(0,0,0,.14) !important;
}

::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,.22) !important;
    border-radius: 20px !important;
}

::-webkit-scrollbar-thumb:hover {
    background: rgba(255,255,255,.34) !important;
}

* {
    scrollbar-width: thin;
}
}
